<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue';
type Revision={id:number;number:number;status:string;feedback:string|null;error:string|null;markdown:string|null;result:unknown};
type Task={id:string;title:string;batch_no:string;case_count:number;prompt?:string;attachments?:{name:string;size:number}[];created_at:string;latest_revision?:Revision;revisions?:Revision[]};
const tasks=ref<Task[]>([]), selected=ref<Task|null>(null), revision=ref<number>(0), feedback=ref(''),error=ref(''),busy=ref(false),tab=ref('report');
const creating=ref(false),title=ref(''),prompt=ref(''),files=ref<File[]>([]);
function chooseFiles(event:Event){files.value=Array.from((event.target as HTMLInputElement).files??[]);}
const labels:Record<string,string>={queued:'等待执行',planning:'任务规划',running:'任务执行',reviewing:'独立审核',revising:'问题返工',finalizing:'最终审核',completed:'已交付',failed:'执行失败',failed_review:'审核未通过',needs_user_input:'待补充信息'};
const stages=['planning','running','reviewing','finalizing','completed'];
const current=computed(()=>selected.value?.revisions?.find(r=>r.number===revision.value));
const terminal=['completed','failed','failed_review','needs_user_input'];
const canFeedback=computed(()=>selected.value?.revisions?.[0]&&terminal.includes(selected.value.revisions[0].status));
async function api(path:string,init?:RequestInit){const response=await fetch('/api'+path,{...init,headers:{Accept:'application/json',...init?.headers}});const data=await response.json();if(!response.ok)throw new Error(Object.values(data.errors??{}).flat().join('；')||data.message||'请求失败');return data;}
async function load(){tasks.value=await api('/tasks');if(selected.value)await select(selected.value.id,false);}
async function select(id:string,reset=true){selected.value=await api('/tasks/'+id);if(reset||!revision.value)revision.value=selected.value!.revisions![0].number;}
async function createTask(){busy.value=true;error.value='';try{const body=new FormData();body.append('title',title.value);body.append('prompt',prompt.value);files.value.forEach(file=>body.append('files[]',file));const task=await api('/tasks',{method:'POST',body});await load();await select(task.id);creating.value=false;title.value='';prompt.value='';files.value=[];}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function sendFeedback(){busy.value=true;error.value='';try{await api('/tasks/'+selected.value!.id+'/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({feedback:feedback.value})});feedback.value='';await select(selected.value!.id);await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
let timer:ReturnType<typeof setInterval>;onMounted(async()=>{try{await load();if(tasks.value[0])await select(tasks.value[0].id);}catch(e){error.value=(e as Error).message;}timer=setInterval(()=>load().catch(e=>error.value=e.message),3000);});onUnmounted(()=>clearInterval(timer));
</script>
<template>
<div class="shell">
<aside><a class="brand" href="/">A<span>↗</span><small>AGENT WORKSPACE</small></a><div class="nav-label">工作空间</div><div class="nav-active">◈　任务指挥台 <span>{{tasks.length}}</span></div><div class="aside-note"><span class="dot"></span> 三角色协同<br><small>指挥官 / 执行官 / 审核官</small></div><footer>WORKSPACE 01<br><small>自主规划 · 工具协作</small></footer></aside>
<main><header><div class="breadcrumb">工作空间 <span>/</span> 任务指挥台</div><div class="header-tag">VUE + LARAVEL</div></header>
<section class="heading"><div><div class="eyebrow">ORCHESTRATE. EXECUTE. VERIFY.</div><h1>把任务交给团队。</h1><p>一次提交，完成执行、独立审核与结构化交付。</p></div><button class="primary" @click="creating=true">＋ 创建任务</button></section>
<div v-if="error" class="error" role="alert">{{error}}<button @click="error=''" aria-label="关闭错误">×</button></div>
<div class="summary"><div><small>全部任务</small><strong>{{tasks.length.toString().padStart(2,'0')}}</strong></div><div><small>运行中</small><strong>{{tasks.filter(t=>!terminal.includes(t.latest_revision?.status??'queued')).length.toString().padStart(2,'0')}}</strong></div><div><small>已交付</small><strong>{{tasks.filter(t=>t.latest_revision?.status==='completed').length.toString().padStart(2,'0')}}</strong></div><div class="summary-copy">每一步都有依据。<br><small>每一版都可追溯。</small></div></div>
<div class="workspace"><section class="task-list"><div class="section-title">任务记录 <small>最近 100 条</small></div><div v-if="!tasks.length" class="empty">还没有任务<br><small>填写需求，开始第一次协作</small></div><button v-for="task in tasks" :key="task.id" class="task-item" :class="{chosen:selected?.id===task.id}" @click="select(task.id).catch(e=>error=e.message)"><div class="task-top"><span class="status" :class="task.latest_revision?.status">{{labels[task.latest_revision?.status??'queued']}}</span><small>TASK</small></div><h3>{{task.title}}</h3><p>{{task.id.slice(0,8)}}</p><small>{{new Date(task.created_at).toLocaleString('zh-CN')}}</small></button></section>
<section class="detail" v-if="selected"><div class="detail-head"><div><div class="eyebrow">TASK / {{selected.id.slice(0,8)}}</div><h2>{{selected.title}}</h2></div><select aria-label="选择任务版本" v-model="revision"><option v-for="r in selected.revisions" :value="r.number" :key="r.number">Revision {{r.number}}</option></select></div>
<div class="task-request" v-if="selected.prompt"><strong>任务需求</strong><p>{{selected.prompt}}</p><small v-for="file in selected.attachments" :key="file.name">附件：{{file.name}} · {{Math.ceil(file.size/1024)}} KB<br></small></div><div class="stages"><div v-for="(stage,index) in stages" :key="stage" :class="{active:current?.status===stage,done:stages.indexOf(current?.status??'')>index}"><span>{{index+1}}</span><small>{{labels[stage]}}</small></div></div>
<div class="tabs"><button :class="{active:tab==='report'}" @click="tab='report'">交付文档</button><button :class="{active:tab==='json'}" @click="tab='json'">JSON 响应</button><span>{{labels[current?.status??'queued']}}</span></div>
<div v-if="current?.error" class="error">{{current.error}}</div><div v-if="current?.status==='failed_review'" class="empty">审核未通过<br><small>可以提交建议，创建新的修订版本。</small></div><div v-else-if="current?.status==='needs_user_input'" class="empty">需要补充任务信息<br><small>请在下方提交补充说明。</small></div><div v-else-if="current?.status==='completed'" class="result"><pre v-if="tab==='report'" class="report">{{current.markdown}}</pre><pre v-else>{{JSON.stringify(current.result,null,2)}}</pre><div class="downloads"><a :href="`/api/tasks/${selected.id}/revisions/${revision}/artifacts/markdown`">↓ Markdown 文档</a><a :href="`/api/tasks/${selected.id}/revisions/${revision}/artifacts/json`">↓ JSON 数据</a></div></div><div v-else-if="current?.status!=='failed'" class="empty progress"><div class="orbit">◈</div><h3>团队正在处理任务</h3><small>当前阶段：{{labels[current?.status??'queued']}}。页面每 3 秒更新。</small></div>
<form class="feedback" @submit.prevent="sendFeedback"><label for="feedback">继续完善这份结果</label><p>提供建议或补充信息，将创建新的修订版本。</p><textarea id="feedback" v-model="feedback" :disabled="!canFeedback||busy" maxlength="10000" placeholder="例如：请增加每个 case 的证据引用，并说明两个模型的差异。"/><button class="primary" :disabled="!canFeedback||busy||!feedback.trim()">提交建议 ↗</button></form></section><section v-else class="detail welcome"><div class="eyebrow">YOUR NEXT TASK STARTS HERE</div><h2>从一个问题开始。</h2><p>填写任务需求并按需上传附件，团队会自主规划、执行与审核。<br>所有结果和修订都保留在这里。</p><button class="primary" @click="creating=true">创建任务</button></section></div>
</main>
<div v-if="creating" class="modal-backdrop" @click.self="!busy&&(creating=false)"><section class="create-dialog" role="dialog" aria-modal="true" aria-labelledby="create-title"><form @submit.prevent="createTask"><h2 id="create-title">创建任务</h2><p>描述目标、期望交付和约束，由团队选择工具与执行方式。</p><label for="task-title">任务名称</label><input id="task-title" v-model="title" required maxlength="200" :disabled="busy" autofocus><label for="task-prompt">任务需求（Prompt）</label><textarea id="task-prompt" v-model="prompt" required maxlength="50000" :disabled="busy" placeholder="你希望完成什么？验收标准是什么？"/><label for="task-files">附件（可选，最多 10 个，共 25 MiB）</label><input id="task-files" type="file" multiple @change="chooseFiles" :disabled="busy"><small v-for="file in files" :key="file.name">{{file.name}}<br></small><div v-if="error" role="alert" class="error">{{error}}</div><div class="dialog-actions"><button type="button" @click="creating=false" :disabled="busy">取消</button><button class="primary" :disabled="busy||!title.trim()||!prompt.trim()">{{busy?'正在提交…':'提交任务 ↗'}}</button></div></form></section></div>
</div>
</template>
